WITH customer_stats AS (SELECT customer_id, COUNT(monthly_fee) AS monthly_fee_count, MAX(monthly_fee) AS max_monthly_fee FROM subscriptions WHERE start_date < '2023-08-26' GROUP BY customer_id) SELECT c.id, c.is_active, cs.monthly_fee_count, cs.max_monthly_fee FROM customers c INNER JOIN customer_stats cs ON c.id = cs.customer_id WHERE cs.max_monthly_fee >= 210 ORDER BY max_monthly_fee DESC
